SourceCode.Declaration:
#mob
/// <summary>
/// XML Formatter class for receive Transfer order lines.
/// </summary>
[TFMTableNameAttribute(tableStr(InventTransferLine),staticMethodStr(MobConstants,Receive))]
class MobXMLFormatOrderLines_ReceiveTransfer extends MobXMLFormatOrderLines_Receive
{
    InventTransferLine      inventTransferLine;

}

Method.Source:
protected void setValues()
{
    super();

    inventTransferLine      = common;
    inventDim               = inventTransferLine.inventDimReceive();

    this.setInventDim(inventTransferLine.ItemId);

    orderBackendId          = MobOrder::constructFromTableName(tableStr(InventTransferTable),orderType).getBackendID(InventTransferTable::find(inventTransferLine.TransferId));//#ReceiveTransferOrderPrefix + inventTransferLine.TransferId;
    lineNumber              = inventTransferLine.InventTransIdReceive;
    itemNumber              = inventTransferLine.ItemId;
    description             = InventTable::find(inventTransferLine.itemId).productName(new xInfo().language());
    quantity                = MobHelper::formatItemQty(inventTransferLine.QtyShipped-inventTransferLine.QtyReceived, inventTransferLine.UnitId);
    registeredQuantity      = MobConstants::NotUsed0();
    unitOfMeasure           = inventTransferLine.UnitId;

    status                  = MobConstants::NotUsed0();
    displayLine1            = inventTransferLine.ItemId;
    displayLine2            = InventTable::find(inventTransferLine.itemId).productName(new xInfo().language());
    displayLine3            = inventDim.wMSLocationId;
    underDeliveryValidation = MobHelper::enumName(enumnum(TFMUnderDeliveryValidation),mobInventDimSetup.registerWMSPallet() ? TFMUnderDeliveryValidation::Block : TFMUnderDeliveryValidation::None); //Must be able to handle partial receipt
    overDeliveryValidation  = MobHelper::enumName(enumnum(TFMUnderDeliveryValidation),mobInventDimSetup.registerWMSPallet() ? TFMUnderDeliveryValidation::Block : TFMUnderDeliveryValidation::None); //Must be able to handle partial receipt
}
